import {resolveAutoTiles} from './auto-tiles.js';
export function renderAutoTileRules(editor){const document=editor.el.ownerDocument,section=document.createElement('section'),heading=document.createElement('h3');heading.textContent='자동 타일 규칙';section.append(heading);const edit=fn=>editor.edit(d=>{fn(d);Object.assign(d,resolveAutoTiles(d));}),button=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=e=>{e.stopPropagation();edit(fn);};return b;};
  for(const [i,rule] of (editor.doc.data.autoTileRules||[]).entries()){const group=document.createElement('details'),summary=document.createElement('summary');summary.textContent='타일 '+rule.source+' → '+rule.index;group.append(summary);for(const [key,label] of [['source','원본 타일'],['index','결과 타일'],['priority','우선순위'],['rotate','회전 일치'],['collision','충돌']]){const row=document.createElement('label'),input=document.createElement('input');row.textContent=label;input.type=typeof rule[key]==='boolean'?'checkbox':'number';if(input.type==='checkbox')input.checked=rule[key];else input.value=rule[key];input.onchange=e=>{e.stopPropagation();edit(d=>d.autoTileRules[i][key]=input.type==='checkbox'?input.checked:Number(input.value));};row.append(input);group.append(row);}const grid=document.createElement('div');Object.assign(grid.style,{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:'4px'});const neighbors=[7,0,1,6,-1,2,5,4,3];for(const n of neighbors){if(n<0){const label=document.createElement('span');label.textContent='중심';grid.append(label);continue;}const select=document.createElement('select');for(const [value,label] of [[-1,'무관'],[0,'다름'],[1,'같음']]){const option=document.createElement('option');option.value=value;option.textContent=label;select.append(option);}select.value=rule.neighbors[n];select.onchange=e=>{e.stopPropagation();edit(d=>d.autoTileRules[i].neighbors[n]=Number(select.value));};grid.append(select);}group.append(grid,button('삭제',d=>d.autoTileRules.splice(i,1)));section.append(group);}
  section.append(button('현재 타일 규칙 추가',d=>{d.autoTileRules??=[];d.autoTileRules.push({id:crypto.randomUUID(),source:editor.tile,index:editor.tile,priority:0,neighbors:Array(8).fill(-1),rotate:false,collision:true});}));editor.properties.append(section);
}
